from pathlib import Path
import json,hashlib,datetime
q=Path(__file__).parent
h=lambda b:hashlib.sha256(b).hexdigest()
rows=[]
for folder in ['pack-native','ordinary']:
 for p in sorted((q/folder/'screenshots').glob('*.jpg')):rows.append({'path':str(p.relative_to(q)),'bytes':p.stat().st_size,'sha256':h(p.read_bytes()),'original':True})
assert len(rows)==30
for folder,name in [('pack-native','controlled'),('ordinary','sidecar-runtime')]:
 assert (q/folder/(name+'.exit')).read_text().strip()=='0'
